/**
 * Standalone entry point. NEVER import from the application or run under the
 * AI operator's security account. No production key is generated by this code.
 */
import { readFile } from "node:fs/promises";
import { createPublicKey } from "node:crypto";
import { z } from "zod";
import { validateConfig } from "./protocol";
import { SafetyController } from "./controller";
import { FileJournal } from "./journal";
import { createAuthorityApp } from "./authority-app";
import { ReviewerNotifications } from "./notifications";

const configPath = process.env.SAFETY_AUTHORITY_CONFIG;
const journalPath = process.env.SAFETY_AUTHORITY_JOURNAL;
const checkpointPath = process.env.SAFETY_AUTHORITY_CHECKPOINT;
const privateKey = process.env.SAFETY_AUTHORITY_SIGNING_KEY;
if (!configPath || !journalPath || !checkpointPath || !privateKey) {
  throw new Error("Independent safety authority configuration, checkpoint, journal and signing key are required");
}
const config = validateConfig(JSON.parse(await readFile(configPath, "utf8")));
if (config.governanceMode !== "founder-only") {
  throw new Error("Future reviewer authority is not activated; an approved Article VI register and procedure are required");
}
const authorityKey = createPublicKey(privateKey);
if (authorityKey.asymmetricKeyType !== "ed25519") throw new Error("Authority receipt key must be Ed25519");
const authorityDer = authorityKey.export({ type: "spki", format: "der" });
if (config.actors.some(actor => authorityDer.equals(createPublicKey(actor.publicKey).export({ type: "spki", format: "der" })))) {
  throw new Error("Authority receipt key must be separate from reviewer, source and operator credentials");
}
const checkpoint = z.object({
  sequence: z.number().int().nonnegative(), head: z.string().regex(/^[a-f0-9]{64}$/),
}).strict().parse(JSON.parse(await readFile(checkpointPath, "utf8")));
if (checkpoint.sequence === 0 && checkpoint.head !== "0".repeat(64)) throw new Error("Invalid initial checkpoint");
const controller = new SafetyController(config, new FileJournal(journalPath, checkpoint));
await controller.initialise();
const notifier = new ReviewerNotifications(controller, config, privateKey);
const notify = () => {
  void notifier.deliver().then(delivered => {
    if (!delivered) console.warn("Independent reviewer notification pending; restrictions remain in force");
  }).catch(() => console.warn("Independent reviewer notification unavailable; restrictions remain in force"));
};
const app = createAuthorityApp(controller, privateKey, notify);
notify();
setInterval(notify, 60_000).unref();
app.listen(8080, "0.0.0.0", () => console.log("Independent safety authority listening on port 8080"));
